"""75 original cases, each with its own technically constrained synthetic UI evidence."""
import json,random,hashlib
from pathlib import Path
ROOT=Path(__file__).parent
MODULES=['🏢 Active Directory ile Tanışma','👤 Kullanıcılar, Gruplar ve Yetkiler','🔐 Parolalar ve Group Policy','🚨 Loglar, Güvenlik ve Şüpheli İşlemler','🕵️ Gerçek Active Directory Denetimi']
TITLE='🔍 Active Directory: Denetçi Gözüyle'
DESCRIPTION='75 Ekran Görüntüsü • 75 Denetim Kararı • Sıfırdan Active Directory\n\nBir şirketin Active Directory ortamını denetlemekle görevlendirildin! Kullanıcı hesaplarını, yönetici yetkilerini, güvenlik gruplarını, parolaları, Group Policy ayarlarını ve şüpheli olayları inceleyeceksin. Active Directory bilmiyor olsan bile sorun değil; her adımda öğrenerek ilerleyeceksin.'
CYCLE=['image','multi_select','choice','scenario','fill_blank','sentence_order','image','drag_select','multi_select','choice','scenario','image','sentence_order','drag_select','image']
rows=[]
def view(tool,title,headers=None,data=None,fields=None,tree=None,tab=None,footer=None):
 return dict(tool=tool,title=title,headers=headers or ['Name','Type','Description'],rows=data or [],fields=fields or [],tree=tree or [],tab=tab or 'General',footer=footer or '')
def add(topic,context,prompt,evidence,choices,knowledge,audit,work,hint,answer=None,kind=None):
 n=len(rows)+1;k=kind or CYCLE[(n-1)%15]
 if k=='fill_blank':opts=[];ans=choices;feedback={}
 else:
  opts=[dict(id=f'k{i+1}',text=t) for i,(t,r) in enumerate(choices)];feedback={f'k{i+1}':r for i,(t,r) in enumerate(choices)}
  ans=answer or ([f'k{i+1}' for i in range(len(opts))] if k=='sentence_order' else ['k1','k2'] if k=='multi_select' else ['k1'])
  random.Random(7513+n).shuffle(opts)
 rows.append(dict(external_id=f'ad-auditor-v1-{n:03}',number=n,chapter=(n-1)//15+1,kind=k,topic=topic,context=context,prompt=prompt,options=opts,answer=ans,feedback=feedback,explanation='💡 Active Directory bilgisi\n'+knowledge+'\n\n🔍 Denetçi gözüyle\n'+audit+'\n\n💼 Gerçek iş hayatında\n'+work,hint=hint,difficulty='beginner' if n<=30 else 'intermediate' if n<=65 else 'advanced',goals=[topic],base_xp=10,published=True,premium=False,order=n,card_pages=[],evidence=evidence,image=f'ad-auditor/screen_{n:03}.png'))
def pick(topic,context,prompt,evidence,good,b,c,d,knowledge,audit,work,hint,kind=None):add(topic,context,prompt,evidence,[good,b,c,d],knowledge,audit,work,hint,kind=kind)
def multi(topic,context,prompt,evidence,items,knowledge,audit,work,hint):add(topic,context,prompt,evidence,items,knowledge,audit,work,hint)
def order(topic,context,evidence,steps,knowledge,audit,work,hint):add(topic,context,'Bu ekranı incelemek için adımları doğru sıraya koy.',evidence,[(s,'Bu adım önceki incelemenin sonucuna bağlıdır.') for s in steps],knowledge,audit,work,hint)
def fill(topic,context,prompt,evidence,answers,knowledge,audit,work,hint):add(topic,context,prompt,evidence,answers,knowledge,audit,work,hint)
